import {today,parseDate,shiftDate,monthEnd,daysBetween,expected,scheduled,balance,initialState,validate,uid,startCycle,checkIn,undoCheckIn,finishCycle,redeem} from './model.js';
const icons={home:'<rect x="4" y="4" width="16" height="16" rx="5"/><path d="m8 12 3 3 5-6"/>',templates:'<rect x="4" y="4" width="6" height="6" rx="2"/><rect x="14" y="4" width="6" height="6" rx="2"/><rect x="4" y="14" width="6" height="6" rx="2"/><rect x="14" y="14" width="6" height="6" rx="2"/>',gift:'<rect x="4" y="10" width="16" height="10" rx="2"/><path d="M3 7h18v4H3zM12 7v13"/><path d="M12 7C4 8 5 1 9 3l3 4c8 1 7-6 3-4z"/>',history:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',coin:'<circle cx="12" cy="12" r="9"/><path d="m12 7 1.5 3.5L17 12l-3.5 1.5L12 17l-1.5-3.5L7 12l3.5-1.5z"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="white"/><circle cx="15" cy="17" r="3" fill="white"/>',leaf:'<path d="M20 4C8 2 2 10 7 16S22 14 20 4Z"/><path d="M4 21 16 9"/>',book:'<path d="M12 5v15M3 4c4-1 7 0 9 2 2-2 5-3 9-2v14c-4-1-7 0-9 2-2-2-5-3-9-2z"/>',run:'<path d="m7 20 4-6-4-4 5-4 4 5h4M3 11l4-1M11 14l5 3v4"/><circle cx="15" cy="3" r="1.5"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'};
export const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.home}</svg>`;
const KEY='habit-seasons-v1';
let state,storageError='',lastRaw=null,page='home',historyTab='cycles',rewardTab='shop',showArchived=false;
const el=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>d.replaceAll('-','.');
const difficulty={easy:'轻松',medium:'适中',hard:'挑战'};
const schedule=t=>t.days.length===7?'每天':`每周 ${[1,2,3,4,5,6,0].filter(d=>t.days.includes(d)).map(d=>['日','一','二','三','四','五','六'][d]).join('、')}`;
const count=c=>state.checkins.filter(x=>x.cycleId===c.id).length;
const rate=c=>Math.round(count(c)/Math.max(expected(c),1)*100);
const cycleNum=c=>state.cycles.filter(x=>x.templateId===c.templateId).findIndex(x=>x.id===c.id)+1;
const tone=t=>t.icon==='leaf'?'green':t.icon==='book'?'orange':'';
const habitIcon=t=>`<div class="habit-icon ${tone(t)}">${icon(t.icon)}</div>`;
function load(){try{lastRaw=localStorage.getItem(KEY);state=lastRaw?validate(JSON.parse(lastRaw)):initialState();if(!lastRaw){localStorage.setItem(KEY,JSON.stringify(state));lastRaw=localStorage.getItem(KEY)}storageError=''}catch(e){state=initialState();storageError='本地数据无法读取或浏览器禁止存储。已有数据不会被覆盖；请先导出原始数据，或导入有效备份。'}}
function commit(fn,{replace=false}={}){if(storageError&&!replace)throw new Error('本地数据暂不可用，请先到数据与设置恢复备份。');const raw=localStorage.getItem(KEY);if(!replace&&raw!==lastRaw){load();render();throw new Error('另一个页面更新了数据，已刷新，请重试。')}const next=structuredClone(state);const result=fn(next);next.revision=(state.revision||0)+1;validate(next);const serialized=JSON.stringify(next);try{localStorage.setItem(KEY,serialized)}catch{throw new Error('保存失败，设备空间不足或浏览器禁止存储。本次操作未生效。')}state=next;lastRaw=serialized;storageError='';render();return result}
let toastTimer;function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3500)}
function modal(title,body){dialog.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${esc(title)}</h2><button class="close" data-action="close" aria-label="关闭">×</button></div><div class="modal-body">${body}<div class="error" role="alert" id="form-error"></div></div>`;if(!dialog.open)dialog.showModal()}
function close(){dialog.close()}
function empty(title,text,button=''){return `<div class="card empty"><div class="empty-icon">${icon(page==='gift'?'gift':page==='history'?'history':'leaf')}</div><h3>${title}</h3><p>${text}</p>${button}</div>`}
const pageButton=(id,text)=>`<button class="btn" data-page="${id}">${text} ${icon('arrow')}</button>`;
function head(title,sub,action=''){return `<div class="page-head"><div><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`}
function home(){const active=state.cycles.filter(c=>c.status==='active'),due=active.filter(c=>scheduled(c,today())),done=due.filter(c=>state.checkins.some(x=>x.cycleId===c.id&&x.date===today())).length,complete=state.cycles.filter(c=>c.status==='completed');return `${head('进行中','把注意力，放在这一期。',`<button class="btn" data-page="templates">${icon('plus')} 开始新一期</button>`)}<div class="stats"><div class="stat"><span class="stat-label">${icon('check')}今日已完成</span><strong>${done} <span class="sub">/ ${due.length}</span></strong><small>${due.length&&done===due.length?'今天的计划，已完成':'一步一步，慢慢来'}</small></div><div class="stat"><span class="stat-label">${icon('home')}进行中的周期</span><strong>${active.length}</strong><small>每一期都有一个终点</small></div><div class="stat"><span class="stat-label">${icon('history')}已完成的周期</span><strong>${complete.length}</strong><small>坚持过的，都在这里</small></div></div><div class="content-grid"><section><div class="section-head"><h2>我的习惯 <span>${active.length?`· ${active.length}`:''}</span></h2><span>${new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date())}</span></div>${active.length?active.map(cycleCard).join(''):empty('给一个习惯，一段时间','选一个想坚持的习惯，设定结束日期。<br>从第一期开始，留下属于你的记录。',pageButton('templates','选择习惯模板'))}</section><aside class="aside"><div class="section-head"><h2>关于这一期</h2></div><div class="card note-card"><span class="kicker">ONE SEASON AT A TIME</span><h3>每一期，都算数。</h3><p>不必承诺永远坚持。<br>认真完成这一段时间，<br>再决定下一次出发。</p><div class="steps"><span>开始</span><i></i><span>坚持</span><i></i><span>收藏</span></div></div>${complete.length?`<div class="card" style="margin-top:18px"><p class="sub">最近完成</p><h3 style="margin-top:12px">${esc(complete.at(-1).snapshot.name)}</h3><p class="sub">第 ${cycleNum(complete.at(-1))} 期 · 已收入历程</p><button class="text-btn" data-page="history">回看我的坚持 ${icon('arrow')}</button></div>`:''}</aside></div>`}
function cycleCard(c){const done=state.checkins.some(x=>x.cycleId===c.id&&x.date===today()),due=scheduled(c,today()),over=today()>c.endDate,future=today()<c.startDate;return `<article class="card habit-card"><div class="card-top"><div class="habit-title">${habitIcon(c.snapshot)}<div><h3>${esc(c.snapshot.name)} <span class="badge">第 ${cycleNum(c)} 期</span></h3><div class="sub">${schedule(c.snapshot)} <span class="coin">· +${c.snapshot.points} Points</span></div></div></div>${due?`<button class="check-btn ${done?'done':''}" data-action="${done?'undo':'check'}" data-id="${c.id}" aria-label="${done?'撤销':'完成'}今日${esc(c.snapshot.name)}">${icon('check')}</button>`:`<span class="badge ${over?'ended':''}">${over?'待归档':future?'尚未开始':'今日休息'}</span>`}</div><div class="progress" role="progressbar" aria-label="计划完成率" aria-valuenow="${rate(c)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${rate(c)}%"></i></div><div class="row meta"><span>${count(c)} / ${expected(c)} 次 · 完成率 ${rate(c)}%</span><span>${future?`${fmt(c.startDate)} 开始`:over?'周期已到期':`还剩 ${Math.max(0,daysBetween(c.endDate,today()))+1} 天`}</span></div><div class="card-footer"><span class="meta">${fmt(c.startDate)} — ${fmt(c.endDate)}</span><button class="text-btn" data-action="detail" data-id="${c.id}">${over?'回顾并归档':'查看这一期'} ${icon('arrow')}</button></div></article>`}
function templates(){const list=state.templates.filter(t=>t.archived===showArchived);return `${head('习惯模板','保存一个想法，在合适的时候开始。',`<button class="btn" data-action="edit-template">${icon('plus')} 新建模板</button>`)}<div class="section-tabs"><button data-action="templates-active" class="${!showArchived?'selected':''}">我的模板</button><button data-action="templates-archived" class="${showArchived?'selected':''}">已停用</button></div><div class="template-grid">${list.map(t=>{const active=state.cycles.find(c=>c.templateId===t.id&&c.status==='active'),total=state.cycles.filter(c=>c.templateId===t.id).length;return `<article class="card"><div class="card-top">${habitIcon(t)}<button class="small-icon" data-action="edit-template" data-id="${t.id}" aria-label="编辑${esc(t.name)}">${icon('more')}</button></div><h3>${esc(t.name)}</h3><p class="sub">${schedule(t)} · ${difficulty[t.difficulty]}</p><div class="row" style="margin-top:20px"><span class="coin">${icon('coin')} ${t.points} <span class="meta">Points / 次</span></span><button class="text-btn" data-action="template-history" data-id="${t.id}">${total?`已开启 ${total} 期`:'尚未开始'}</button></div><div class="card-footer">${t.archived?`<button class="btn secondary full" data-action="restore-template" data-id="${t.id}">恢复模板</button>`:active?`<button class="btn outline full" data-action="detail" data-id="${active.id}">第 ${cycleNum(active)} 期进行中 ${icon('arrow')}</button>`:`<button class="btn outline full" data-action="start" data-id="${t.id}">${icon('plus')} Start · 开始一期</button>`}</div></article>`}).join('')}</div>${!list.length?empty('这里还没有模板','创建一个习惯模板，再为它开始新的一期。'):''}<p class="hint">${icon('lock')}修改模板只影响以后开始的周期，过去的记录会保留。</p>`}
function rewards(){return `${head('奖励','把积累的每一步，换成喜欢的事。',`<button class="btn" data-action="edit-reward">${icon('plus')} 添加奖励</button>`)}<div class="card balance-card"><div><p class="sub">可用积分</p><strong>${balance(state).toLocaleString()} <span style="font-size:15px;font-weight:400">Points</span></strong><p class="sub">累计获得 ${state.checkins.reduce((a,c)=>a+c.points,0)} · 已兑换 ${state.redemptions.reduce((a,r)=>a+r.cost,0)}</p></div>${icon('coin')}</div><div class="section-tabs"><button data-action="reward-shop" class="${rewardTab==='shop'?'selected':''}">我的奖励</button><button data-action="reward-history" class="${rewardTab==='history'?'selected':''}">兑换记录 · ${state.redemptions.length}</button></div>${rewardTab==='history'?(state.redemptions.length?`<div class="card list">${[...state.redemptions].reverse().map(r=>`<div class="history-row"><div class="habit-title"><div class="habit-icon orange">${icon('gift')}</div><div><h3>${esc(r.name)}</h3><p class="sub">${new Date(r.redeemedAt).toLocaleString('zh-CN')}</p></div></div><span class="coin">−${r.cost} Points</span></div>`).join('')}</div>`:empty('还没有兑换记录','完成习惯、积累积分，再给自己一个奖励。')):`<div class="reward-grid">${state.rewards.filter(r=>!r.archived).map(r=>`<article class="card"><div class="card-top"><div class="habit-icon orange">${icon('gift')}</div><button class="small-icon" data-action="edit-reward" data-id="${r.id}" aria-label="编辑${esc(r.name)}">${icon('more')}</button></div><h3>${esc(r.name)}</h3><div class="card-footer"><span class="reward-price">${r.cost} <small>Points</small></span><button class="btn ${balance(state)<r.cost?'secondary':''}" data-action="redeem" data-id="${r.id}" ${balance(state)<r.cost?'disabled':''}>${balance(state)<r.cost?`还差 ${r.cost-balance(state)}`:'兑换'}</button></div></article>`).join('')}</div>${!state.rewards.some(r=>!r.archived)?empty('留一个期待给自己','添加一个现实中的奖励，为它设置积分价格。'):''}${state.rewards.some(r=>r.archived)?`<button class="text-btn" data-action="archived-rewards">管理已停用的奖励</button>`:''}`}`}
function history(){const closed=state.cycles.filter(c=>c.status!=='active'),complete=closed.filter(c=>c.status==='completed'),names=[...new Set(complete.map(c=>c.templateId))];return `${head('历程','那些认真坚持过的时间，都有迹可循。')}<div class="stats"><div class="stat"><span class="stat-label">完成的周期</span><strong>${complete.length}</strong><small>到达终点，并确认完成</small></div><div class="stat"><span class="stat-label">完成过的习惯</span><strong>${names.length}</strong><small>不同习惯的累计记录</small></div><div class="stat"><span class="stat-label">累计执行</span><strong>${state.checkins.length}</strong><small>每一次行动，都算数</small></div></div><div class="section-tabs"><button data-action="history-cycles" class="${historyTab==='cycles'?'selected':''}">全部周期</button><button data-action="history-completed" class="${historyTab==='completed'?'selected':''}">完成过的习惯</button></div>${historyTab==='cycles'?(closed.length?`<div class="card list">${[...closed].reverse().map(historyRow).join('')}</div>`:empty('这一页，留给以后的你','完成或提前结束的周期会出现在这里。<br>模板会一直保留，随时可以再出发。')):(names.length?`<div class="template-grid">${names.map(id=>{const cycles=complete.filter(c=>c.templateId===id),last=cycles.at(-1);return `<article class="card">${habitIcon(last.snapshot)}<h3 style="margin-top:18px">${esc(last.snapshot.name)}</h3><p class="sub">完成 ${cycles.length} 期 · 执行 ${cycles.reduce((a,c)=>a+count(c),0)} 次</p><button class="text-btn" data-action="template-history" data-id="${id}">回看每一期 ${icon('arrow')}</button></article>`}).join('')}</div>`:empty('还没有完成过的习惯','一期到达结束日期，并由你确认完成后，<br>它就会出现在这里。'))}`}
function historyRow(c){return `<div class="history-row"><button class="habit-title" style="text-align:left;padding:0" data-action="detail" data-id="${c.id}">${habitIcon(c.snapshot)}<div><h3>${esc(c.snapshot.name)} <span class="meta">第 ${cycleNum(c)} 期</span></h3><p class="sub">${fmt(c.startDate)} — ${fmt(c.endedAt||c.endDate)}</p><p class="sub">${count(c)} / ${expected(c)} 次 · 完成率 ${rate(c)}%</p></div></button><span class="badge ${c.status==='completed'?'success':c.status==='ended'?'ended':''}">${c.status==='completed'?'已完成':c.status==='ended'?'提前结束':'进行中'}</span></div>`}
function settings(){return `${head('数据与设置','留住这些记录，陪你走得更远。')}<div class="card list"><div class="settings-row"><div><h3>导出数据备份</h3><p>模板、所有周期、打卡与兑换记录，保存在一个 JSON 文件里。</p><p>${state.lastExportAt?`最近导出：${new Date(state.lastExportAt).toLocaleString('zh-CN')}`:'还没有导出过备份，建议每月保存一次。'}</p></div><button class="btn outline" data-action="export">导出备份</button></div><div class="settings-row"><div><h3>从备份恢复</h3><p>导入前会校验记录。恢复将替换当前数据，请先导出备份。</p></div><button class="btn secondary" data-action="import">导入备份</button><input id="import-file" type="file" accept=".json,application/json" hidden></div><div class="settings-row"><div><h3>添加到手机主屏幕</h3><p>iPhone：在 Safari 打开，点分享，再选择「添加到主屏幕」。<br>Android：在浏览器菜单选择「安装应用」或「添加到主屏幕」。<br>首次联网打开后，即可离线使用。</p></div></div><div class="settings-row"><div><h3>只保存在这台设备</h3><p>无需账号，不上传记录，也不会跨设备同步。清理浏览器数据、更换浏览器或设备前，请先导出。请固定使用同一个网址和入口。</p></div></div></div><p class="hint">一期 · 版本 1.0 · 数据格式 v1</p>`}
function render(){el.innerHTML=`<aside class="sidebar"><div class="brand"><img src="./icon.svg" alt=""><div>一期<small>HABIT SEASONS</small></div></div><nav class="nav" aria-label="主导航">${[['home','进行中'],['templates','习惯模板'],['gift','奖励'],['history','历程']].map(([id,n])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}${n}</button>`).join('')}</nav><div class="sidebar-bottom"><button data-page="settings">${icon('settings')}数据与设置</button><div class="local-note">只在这台设备上，属于你。<br>本地存储 · 无需账号</div></div></aside><main class="main"><div class="topbar"><span class="eyebrow">一期 · HABIT SEASONS</span><div class="top-right"><button class="wallet-pill" data-page="gift"><span class="coin">${icon('coin')}</span><b>${balance(state)}</b> Points</button><button class="mobile-settings" data-page="settings" aria-label="数据与设置">${icon('settings')}</button></div></div>${storageError?`<div class="card" role="alert" style="margin-bottom:20px;color:#c44738"><p>${esc(storageError)}</p><button class="text-btn" data-action="export">导出原始数据</button></div>`:''}${({home,templates,gift:rewards,history,settings}[page]||home)()}${page==='home'?`<p class="hint">${icon('lock')}你的记录只保存在当前设备，记得定期备份。</p>`:''}</main>`}
function templateForm(id){const t=state.templates.find(t=>t.id===id)||{name:'',icon:'home',difficulty:'medium',points:10,days:[0,1,2,3,4,5,6]};modal(id?'编辑习惯模板':'新建习惯模板',`<form id="template-form" data-id="${id||''}"><label for="name">习惯名称</label><input id="name" name="name" required maxlength="60" placeholder="你想开始什么习惯？" value="${esc(t.name)}"><div class="field-row"><div><label for="habit-icon">图标</label><select id="habit-icon" name="icon">${[['home','日常'],['leaf','健康'],['run','运动'],['book','学习']].map(([v,n])=>`<option value="${v}" ${t.icon===v?'selected':''}>${n}</option>`).join('')}</select></div><div><label for="difficulty">难度</label><select id="difficulty" name="difficulty">${Object.entries(difficulty).map(([v,n])=>`<option value="${v}" ${t.difficulty===v?'selected':''}>${n}</option>`).join('')}</select></div></div><label for="points">每次完成获得积分</label><input id="points" name="points" type="number" min="1" max="1000" required value="${t.points}"><p class="form-note">轻松默认 5，适中 10，挑战 20；也可以自行调整。</p><label>每周执行日</label><div class="days">${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="day" value="${d}" ${t.days.includes(d)?'checked':''}><span>${['日','一','二','三','四','五','六'][d]}</span></label>`).join('')}</div><p class="form-note">每天最多打卡一次。设置只用于以后新开始的周期。</p><div class="modal-actions">${id?`<button class="btn secondary" type="button" data-action="${t.archived?'restore-template':'archive-template'}" data-id="${id}">${t.archived?'恢复模板':'停用模板'}</button>`:''}<button class="btn" type="submit">保存模板</button></div></form>`)}
function startForm(id){const t=state.templates.find(t=>t.id===id);modal('开始新的一期',`<form id="start-form" data-id="${id}"><div class="habit-title">${habitIcon(t)}<div><h3>${esc(t.name)}</h3><p class="sub" style="margin:5px 0 0">${schedule(t)} · +${t.points} Points / 次</p></div></div><label for="start-date">开始日期</label><input type="date" id="start-date" name="startDate" min="${today()}" value="${today()}" required><label for="duration">这一期持续多久</label><select id="duration" name="duration"><option value="1">1 个月</option><option value="4" selected>4 个月</option><option value="6">6 个月</option><option value="12">1 年</option><option value="custom">自定义结束日期</option></select><label for="end-date">结束日期（含当天）</label><input type="date" id="end-date" name="endDate" min="${today()}" value="${monthEnd(today(),4)}" required><p class="form-note">开始后，本期设置将固定保存。到期时回顾并归档，以后可以再开始新的一期。</p><div class="modal-actions"><button class="btn" type="submit">Start · 开始第 ${state.cycles.filter(c=>c.templateId===id).length+1} 期 ${icon('arrow')}</button></div></form>`)}
function detail(id){const c=state.cycles.find(c=>c.id===id),logs=state.checkins.filter(x=>x.cycleId===id),start=shiftDate(today(),-27),until=c.status==='active'?today():c.endedAt,elapsed=expected(c,until),isActive=c.status==='active';modal(`${c.snapshot.name} · 第 ${cycleNum(c)} 期`,`<p>${schedule(c.snapshot)} · ${difficulty[c.snapshot.difficulty]} · 每次 +${c.snapshot.points} Points<br>计划：${fmt(c.startDate)} — ${fmt(c.endDate)}${c.endedAt?`<br>实际结束：${fmt(c.endedAt)} · ${c.status==='completed'?'已完成':'提前结束'}`:''}</p><div class="detail-stats"><div>完成次数<strong>${logs.length} / ${expected(c)}</strong></div><div>计划完成率<strong>${rate(c)}%</strong></div><div>获得积分<strong>${logs.reduce((a,x)=>a+x.points,0)}</strong></div></div><p>截至${isActive?'今天':'结束'}应执行 ${elapsed} 次，已执行 ${logs.length} 次。${c.status==='ended'?'完成率仍以原计划为分母。':''}</p><h3 style="font-size:14px">最近 28 天</h3><div class="calendar">${Array.from({length:28},(_,i)=>{const d=shiftDate(start,i),hit=logs.some(x=>x.date===d);return `<span class="${hit?'hit':!scheduled(c,d)?'na':''}" title="${d} · ${hit?'已完成':scheduled(c,d)?'未完成':'非执行日'}">${+d.slice(-2)}</span>`}).join('')}</div><p class="form-note">蓝色表示已完成。以下保留本期所有打卡日期。</p>${logs.length?`<details><summary style="font-size:14px;cursor:pointer">全部 ${logs.length} 次打卡</summary><div style="max-height:180px;overflow:auto;margin-top:12px">${[...logs].reverse().map(x=>`<div class="row sub" style="padding:7px 0"><span>${fmt(x.date)}</span><span>+${x.points} Points</span></div>`).join('')}</div></details>`:''}${isActive?`<div class="modal-actions"><button class="btn secondary" data-action="finish-ended" data-id="${id}" ${today()<c.startDate?'disabled':''}>提前结束</button><button class="btn" data-action="finish-completed" data-id="${id}" ${today()<c.endDate?'disabled':''}>完成并归档</button></div>${today()<c.endDate?'<div class="form-note">到达计划结束日期后，可以确认完成并归档。</div>':''}`:`<div class="modal-actions"><button class="btn" data-action="start-again" data-id="${c.templateId}">再开始新的一期</button></div>`}`)}
function rewardForm(id){const r=state.rewards.find(x=>x.id===id)||{name:'',cost:300};modal(id?'编辑奖励':'添加一个奖励',`<form id="reward-form" data-id="${id||''}"><label for="name">奖励名称</label><input id="name" name="name" required maxlength="60" placeholder="一件值得期待的事" value="${esc(r.name)}"><label for="cost">兑换所需积分</label><input type="number" id="cost" name="cost" min="1" max="1000000" required value="${r.cost}"><p class="form-note">兑换会扣除全局积分，并保留当时的奖励名称和价格。</p><div class="modal-actions">${id?`<button type="button" class="btn secondary" data-action="archive-reward" data-id="${id}">停用奖励</button>`:''}<button class="btn" type="submit">保存奖励</button></div></form>`)}
function confirm(title,body,action,id,label='确认'){modal(title,`<p>${body}</p><div class="modal-actions"><button class="btn secondary" data-action="close">取消</button><button class="btn" data-action="${action}" data-id="${id}">${label}</button></div>`)}
function download(content,filename){const url=URL.createObjectURL(new Blob([content],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let pendingImport=null;
const actions={
 close, 'edit-template':templateForm,start:startForm,detail,'edit-reward':rewardForm,
 'templates-active':()=>{showArchived=false;render()},'templates-archived':()=>{showArchived=true;render()},
 'reward-shop':()=>{rewardTab='shop';render()},'reward-history':()=>{rewardTab='history';render()},
 'history-cycles':()=>{historyTab='cycles';render()},'history-completed':()=>{historyTab='completed';render()},
 check:id=>{const points=commit(s=>checkIn(s,id));toast(`完成今天的一步，+${points} Points`)},
 undo:id=>confirm('撤销今天的打卡？','会同时扣回本次获得的积分。','confirm-undo',id,'撤销打卡'),
 'confirm-undo':id=>{commit(s=>undoCheckIn(s,id));close();toast('已撤销今日打卡')},
 'archive-template':id=>{commit(s=>{s.templates.find(t=>t.id===id).archived=true});close();toast('模板已停用，周期和历史仍然保留')},
 'restore-template':id=>{commit(s=>{s.templates.find(t=>t.id===id).archived=false});close();toast('模板已恢复')},
 'archive-reward':id=>{commit(s=>{s.rewards.find(r=>r.id===id).archived=true});close();toast('奖励已停用，兑换记录仍然保留')},
 'restore-reward':id=>{commit(s=>{s.rewards.find(r=>r.id===id).archived=false});close();toast('奖励已恢复')},
 'archived-rewards':()=>modal('已停用的奖励',state.rewards.filter(r=>r.archived).map(r=>`<div class="history-row"><span>${esc(r.name)}</span><button class="btn secondary" data-action="restore-reward" data-id="${r.id}">恢复</button></div>`).join('')),
 'template-history':id=>{const cycles=state.cycles.filter(c=>c.templateId===id);modal('每一期的记录',cycles.length?[...cycles].reverse().map(historyRow).join(''):'<p>这个习惯还没有开始过。选一个时间，开启第一期。</p>')},
 'start-again':id=>{const t=state.templates.find(t=>t.id===id);if(t.archived)throw new Error('请先在习惯模板中恢复这个模板。');const c=state.cycles.find(c=>c.templateId===id&&c.status==='active');if(c){detail(c.id);return}startForm(id)},
 'finish-ended':id=>confirm('提前结束这一期？','已经执行过的每一次都会保留，获得的积分不变。这一期会记为「提前结束」，不计入完成的周期。','confirm-ended',id,'结束并归档'),
 'finish-completed':id=>{const c=state.cycles.find(c=>c.id===id);confirm('完成这一期',`本期执行了 ${count(c)} / ${expected(c)} 次，完成率 ${rate(c)}%。归档后不能继续打卡，模板会保留。`,'confirm-completed',id,'完成并归档')},
 'confirm-ended':id=>{commit(s=>finishCycle(s,id,'ended'));close();toast('这一期已收入历程')},
 'confirm-completed':id=>{commit(s=>finishCycle(s,id,'completed'));close();toast('又认真走完了一期，已收入历程')},
 redeem:id=>{const r=state.rewards.find(r=>r.id===id);confirm('兑换这个奖励？',`${esc(r.name)} · ${r.cost} Points。兑换后余额为 ${balance(state)-r.cost} Points。确认后保留兑换记录，请在现实中享受这个奖励。`,'confirm-redeem',id,'确认兑换')},
 'confirm-redeem':id=>{commit(s=>redeem(s,id));close();toast('兑换成功，好好奖励自己')},
 export:()=>{if(storageError){download(lastRaw||localStorage.getItem(KEY)||'{}',`一期-原始数据-${today()}.json`);return}const copy=structuredClone(state);copy.lastExportAt=new Date().toISOString();download(JSON.stringify(copy,null,2),`一期-备份-${today()}.json`);commit(s=>{s.lastExportAt=copy.lastExportAt});toast('已导出，请妥善保存备份文件')},
 import:()=>document.querySelector('#import-file').click(),
 'confirm-import':()=>{if(!pendingImport)throw new Error('请重新选择备份文件。');validate(pendingImport);commit(s=>{for(const k of Object.keys(s))delete s[k];Object.assign(s,structuredClone(pendingImport))},{replace:true});pendingImport=null;close();toast('备份已恢复')}
};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.page){page=b.dataset.page;render();window.scrollTo(0,0);return}const action=b.dataset.action;if(actions[action])try{actions[action](b.dataset.id)}catch(err){if(dialog.open)document.querySelector('#form-error').textContent=err.message;else toast(err.message)}});
document.addEventListener('submit',e=>{if(!e.target.matches('#template-form,#start-form,#reward-form'))return;e.preventDefault();const f=e.target,data=new FormData(f),id=f.dataset.id;try{if(f.id==='template-form'){const fields={name:data.get('name').trim(),icon:data.get('icon'),difficulty:data.get('difficulty'),points:Number(data.get('points')),days:data.getAll('day').map(Number)};if(!fields.days.length)throw new Error('请至少选择一个执行日。');commit(s=>{if(id)Object.assign(s.templates.find(t=>t.id===id),fields);else s.templates.push({id:uid(),...fields,archived:false})});toast('模板已保存')}if(f.id==='start-form'){commit(s=>startCycle(s,id,data.get('startDate'),data.get('endDate')));page='home';render();toast('新的一期，从这里开始')}if(f.id==='reward-form'){const fields={name:data.get('name').trim(),cost:Number(data.get('cost'))};commit(s=>{if(id)Object.assign(s.rewards.find(r=>r.id===id),fields);else s.rewards.push({id:uid(),...fields,archived:false})});toast('奖励已保存')}close()}catch(err){document.querySelector('#form-error').textContent=err.message}});
document.addEventListener('change',async e=>{if(e.target.id==='difficulty')document.querySelector('#points').value={easy:5,medium:10,hard:20}[e.target.value];if(['duration','start-date'].includes(e.target.id)){const start=document.querySelector('#start-date').value,n=document.querySelector('#duration').value;if(start){document.querySelector('#end-date').min=start;if(n!=='custom')document.querySelector('#end-date').value=monthEnd(start,Number(n))}}if(e.target.id==='end-date')document.querySelector('#duration').value='custom';if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw new Error('文件超过 10 MB，请检查是否为正确的备份。');pendingImport=validate(JSON.parse(await file.text()));confirm('恢复这份备份？',`备份含 ${pendingImport.templates.length} 个模板、${pendingImport.cycles.length} 个周期、${pendingImport.checkins.length} 次打卡和 ${pendingImport.redemptions.length} 次兑换，可用积分 ${balance(pendingImport)}。当前数据将被替换；请确认已保存当前备份。`,'confirm-import','','替换并恢复')}catch(err){pendingImport=null;toast(err instanceof SyntaxError?'无法读取 JSON，请选择正确的备份文件。':err.message)}e.target.value=''}});
window.addEventListener('storage',e=>{if(e.key===KEY){load();close();render();toast('记录已与另一个页面同步')}});
let currentDay=today();document.addEventListener('visibilitychange',()=>{if(!document.hidden&&currentDay!==today()){currentDay=today();render()}});setInterval(()=>{if(currentDay!==today()){currentDay=today();render()}},60000);
load();render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('离线缓存暂未启用，请联网重新打开一次。'));
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_habit_seasons',title:'查看习惯周期',description:'读取当前习惯周期、完成次数和可用积分，不修改数据。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw new Error('不接受参数');return {balance:balance(state),cycles:state.cycles.map(c=>({id:c.id,name:c.snapshot.name,status:c.status,startDate:c.startDate,endDate:c.endDate,completed:count(c),planned:expected(c)}))}}})).catch(()=>{})}catch{}}
